TOPICS=[
('Сайты и заявки','Почему сайт получает просмотры, но мало обращений?',['Проверьте, понятно ли предложение с первого экрана.','Покажите услуги и реальные примеры работ.','Сделайте форму короткой и удобной.','Проверьте отправку заявки на телефоне.','Обсудим, что мешает вашим клиентам оставить заявку.']),
('Маркетинг','Что проверить до запуска Яндекс Директ?',['Сформулируйте, кому и что вы предлагаете.','Проверьте посадочную страницу и контакты.','Подготовьте цели аналитики и UTM.','Разделите тесты по гипотезам и ограничьте бюджет.','Оценивайте обращения и продажи, а не только клики.']),
('VK и Авито','Как подготовить предложение для VK и Авито?',['Выберите понятный клиенту результат услуги.','Подготовьте свои фото и описание.','Укажите условия и способ связи.','Свяжите заявки с CRM и источником.','Проверьте обработку каждого обращения.']),
('Продвижение на картах','Что проверить в карточке бизнеса на картах?',['Название, адрес и часы должны быть актуальными.','Добавьте свои фотографии и описание услуг.','Проверьте телефон и ссылку на сайт.','Отвечайте на реальные отзывы.','Считайте обращения из карточки отдельно.']),
('CRM','Когда бизнесу нужна CRM?',['Запишите этапы движения заявки.','Назначьте ответственного за каждый этап.','Настройте задачи и напоминания.','Подключайте источники с согласованными доступами.','Проверьте отчёт по потерянным обращениям.']),
('Лидогенерация звонками','Как подготовить лидогенерацию на звонках?',['Определите целевого клиента и допустимые источники контактов.','Согласуйте сценарий и порядок отказа от контакта.','Обучите исполнителя понимать задачу клиента.','Фиксируйте результат разговора в CRM.','Считайте квалифицированные обращения и сделки.']),
('Отдел продаж','С чего начать построение отдела продаж?',['Опишите путь клиента от заявки до сделки.','Разделите роли и ответственность.','Подготовьте обучение и разбор разговоров.','Настройте CRM и регулярную обратную связь.','Сравнивайте изменения по фактическим данным.']),
('ИИ-контент','Как подготовить ИИ-рекламу и коммерческое видео?',['Сформулируйте задачу, аудиторию и сценарий.','Подготовьте материалы с правами на использование.','Согласуйте сцены и формат результата.','Проверьте текст, монтаж и достоверность обещаний.','Одобрите конкретную версию перед публикацией.']),
('ИИ-фильмы и мультфильмы','Что нужно для ИИ-фильма или мультфильма?',['Идея, персонажи и последовательный сценарий.','Права на изображения, музыку и голоса.','Раскадровка и единый визуальный стиль.','Монтаж, титры и проверка сцен.','План времени и ресурсов до начала производства.']),
('Автоматизация','Как выбрать первую автоматизацию?',['Найдите регулярно повторяющуюся задачу.','Запишите входные данные и ожидаемый результат.','Сохраните ручное подтверждение важных действий.','Подготовьте обработку ошибок и уведомления.','Измерьте пользу на небольшом пилоте.'])]
def make_plan(days=14):
 if not 1<=days<=30:raise ValueError('Plan horizon 1–30 days')
 items=[]
 for n in range(days):
  title,hook,cards=TOPICS[n%len(TOPICS)];angle='Чек-лист' if n<len(TOPICS) else 'Разбор процесса'
  selected=cards if n<len(TOPICS) else list(reversed(cards))
  text=angle+': '+hook+'\n'+'\n'.join(f'{i+1}. {v}' for i,v in enumerate(selected))+'\nОбсудим вашу задачу: https://stanislavweb.ru · Telegram @Butov52'
  items.append({'day':n+1,'state':'DRAFT','topic':title,'text':text,'carousel':{'title':title,'cards':selected,'cta':'stanislavweb.ru · @Butov52'},'script':{'hook':hook,'scenes':selected,'cta':'Напишите @Butov52'},'rights_note':'Оригинальный текстовый черновик. Визуальные материалы требуют собственных/лицензированных assets.'})
 return items
if __name__=='__main__':
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--days',type=int,default=14);a=p.parse_args();print(json.dumps(make_plan(a.days),ensure_ascii=False,indent=2))
